'use strict';
const connections=EldoriaConnectionsModel,connectionCSS=document.createElement('link');connectionCSS.rel='stylesheet';connectionCSS.href='city-connections.css?v=routes-1';document.head.append(connectionCSS);
// Keep every route used by cottage activities reciprocal with the room's own return route.
for(const [id,links]of Object.entries(connections.cottage))cottageConnections[id]=[...links];
const connectionPanel=document.createElement('section');connectionPanel.id='cityConnections';connectionPanel.setAttribute('aria-label','Connected entrances and destination views');$('cityRoomTrail').after(connectionPanel);
function connectionKey(){return cityInside==='owlTreehouse'?(cityTreehousePorch?'owlPorch':'owlRoom'):(cityInside||'@'+scene)}
function connectionGraph(){const g=connections.graph(scene,scenes[scene].buildings.map(b=>b[3]));if(scene==='forest'){g['@forest']=(g['@forest']||[]).filter(x=>x!=='owlTreehouse');g.owlPorch=['@forest','owlRoom'];g.owlRoom=['owlPorch'];g['@forest'].push('owlPorch');delete g.owlTreehouse}return g}
function connectionName(id){if(id==='owlPorch')return 'Aurelin’s treehouse stairs';if(id==='owlRoom')return 'Aurelin’s story room';return id.startsWith('@')?cityShort[id.slice(1)]+' · outside':cityRoomNames[id]||id}
function connectionPhoto(id){const night=window.ELDORIA_SKY?.phase==='night';if(id.startsWith('@')||id==='owlPorch'){const entry=id==='owlPorch'?['city-c',3]:cityPhotoCatalog[id.slice(1)];return{url:'assets/city/'+entry[0]+(night?'-night':'')+'.webp',cell:entry[1],atlas:true}}const room=id==='owlRoom'?'owlTreehouse':id,image=room==='willowLane'&&night?'willow-lane-night':comfortRoomImage(room),sheltered=!cottageRoom(room)?.outside&&room!=='willowLane';const natural=sheltered?window.ELDORIA_NATURAL_INTERIORS?.photoFor(image):null;if(natural)return natural;return{url:'assets/interiors/'+image+'.jpg',cell:0,atlas:false}}
function connectionPaint(el,id){const p=connectionPhoto(id);el.style.backgroundImage='url("'+p.url+'")';el.style.backgroundSize=p.atlas?'200% 200%':'cover';el.style.backgroundPosition=p.atlas?(p.cell%2?'100%':'0%')+' '+(p.cell>1?'100%':'0%'):'center';el.dataset.photoUrl=p.url;el.dataset.photoCell=p.cell;el.dataset.destination=id}
let connectionHistory=[];try{const saved=JSON.parse(sessionStorage.getItem('eldoria-door-route')||'[]');if(Array.isArray(saved)&&saved.every(x=>typeof x==='string'))connectionHistory=saved}catch{}
function connectionBack(){const key=connectionKey(),g=connectionGraph();if(connectionHistory[connectionHistory.length-1]!==key)connectionHistory=connections.path(g,'@'+scene,key);return connectionHistory.length>1?connectionHistory[connectionHistory.length-2]:(key==='owlRoom'?'owlPorch':connections.back(scene,cityInside))}
function connectionVisible(id){return !countyHidden.includes(id)||promise.active(state)}
function connectionGo(id){if(!connectionGraph()[connectionKey()]?.includes(id))return;const previous=connectionKey();connectionBack();const oldHistory=[...connectionHistory],index=connectionHistory.indexOf(id);connectionHistory=index<0?[...connectionHistory,id]:connectionHistory.slice(0,index+1);$('modal').close();if(id.startsWith('@')){connectionLeaveStreet();}else if(id==='owlRoom'){cityEnterStoryRoom()}else if(id==='owlPorch'){if(cityInside==='owlTreehouse'){cityTreehousePorch=true;state.cityView={district:'forest',room:'owlTreehouse',porch:true};persist();cityDraw()}else cityEnter('owlTreehouse')}else cityEnter(id);if(connectionKey()===previous)connectionHistory=oldHistory;try{sessionStorage.setItem('eldoria-door-route',JSON.stringify(connectionHistory))}catch{}if(connectionKey()!==previous)cityMessage('From '+connectionName(previous)+' → '+connectionName(connectionKey())+'.');}
function connectionPreview(id){const previous=connectionKey();modal('Through to '+connectionName(id),'<p>From '+lifeEsc(connectionName(previous))+' to '+lifeEsc(connectionName(id))+'. This is the view you will enter.</p><div id="connectionDoorView" role="img"></div>');const view=$('connectionDoorView');view.setAttribute('aria-label',connectionName(id)+' · destination view');connectionPaint(view,id);action('Walk through to '+connectionName(id),()=>connectionGo(id));action('Stay here',()=>$('modal').close())}
const connectionLeaveStreet=cityLeave;cityLeave=function(){if(!cityInside)return;const here=connectionKey(),back=connectionBack();if(back.startsWith('@'))connectionLeaveStreet();else if(connectionGraph()[here]?.includes(back))connectionGo(back);else connectionLeaveStreet()};
let connectionRoutes=[],connectionPhotoKey='';
function connectionLayout(){const a=cityPhotoLayout,art=$('citySceneArt');if(!a)return;const n=a.atlas?2:1,g=EldoriaElfPlacement.crop(art.clientWidth,art.clientHeight,a.width/n,a.height/n);for(const pin of $('cityHotspots').querySelectorAll('.connection-pin')){pin.style.setProperty('--route-left',g.left+Number(pin.dataset.anchorX)*g.width/100+'px');pin.style.setProperty('--route-top',g.top+Number(pin.dataset.anchorY)*g.height/100+'px')}}
function connectionRoutesDraw(){const key=connectionKey(),g=connectionGraph();connectionRoutes=(g[key]||[]).filter(connectionVisible);connectionPanel.replaceChildren();const heading=document.createElement('h3');heading.textContent=cityInside?'From this room':'Entrances & paths';connectionPanel.append(heading);const info=document.createElement('p');info.textContent=cityInside?'Choose a connected room below. Turn back to return through the entrance you used.':'The numbered markers follow the doors and paths in the photograph. Each picture below shows the actual destination.';connectionPanel.append(info);const grid=document.createElement('div');grid.className='connection-grid';connectionPanel.append(grid);const markers=new Map();connectionRoutes.forEach(id=>{const xy=connections.anchor(scene,cityInside?connectionKey():null,id);if(xy)markers.set(id,xy)});const numbered=[...markers].sort((a,b)=>a[1][0]-b[1][0]);const numbers=new Map(numbered.map(([id],i)=>[id,i+1]));for(const id of [...connectionRoutes].sort((a,b)=>(markers.get(a)?.[0]??150)-(markers.get(b)?.[0]??150))){const card=document.createElement('article');card.className='connection-card';card.dataset.route=id;const preview=document.createElement('button');preview.className='connection-photo';preview.setAttribute('aria-label','Look through to '+connectionName(id));connectionPaint(preview,id);preview.onclick=()=>connectionPreview(id);const title=document.createElement('strong');title.textContent=(numbers.has(id)?numbers.get(id)+'. ':'')+connectionName(id);const hint=document.createElement('small');hint.textContent=markers.has(id)?(markers.get(id)[0]<40?'Left side of the photograph':markers.get(id)[0]>65?'Right side of the photograph':'Center of the photograph'):id===connectionBack()?'Turn back · return the way you came':cityInside?'Connected room · doorway outside this camera view':'Follow the path beyond this view';const enter=document.createElement('button');enter.textContent=(id===connectionBack()?'Return to ':'Walk to ')+connectionName(id);enter.dataset.connection=id;enter.onclick=()=>connectionGo(id);card.append(preview,title,hint,enter);grid.append(card);if(markers.has(id)){const xy=markers.get(id),pin=cityTarget(String(numbers.get(id)),xy[0],xy[1],()=>connectionPreview(id),'door connection-pin',id);pin.dataset.anchorX=xy[0];pin.dataset.anchorY=xy[1];pin.setAttribute('aria-label',numbers.get(id)+'. '+connectionName(id));pin.title=connectionName(id)}}connectionLayout();connectionPhotoKey=window.ELDORIA_SKY?.phase+':'+atmosphere.conditions(state).weather}
const connectionHotspotsBefore=cityBuildHotspots;cityBuildHotspots=function(){connectionHotspotsBefore();for(const button of [...$('cityHotspots').children])if(button.matches('.door,.exit,.path')||(button.matches('.work')&&cityInside!=='countyCamp'))button.remove();connectionRoutesDraw()};
cityBuildRoomTrail=function(){const trail=$('cityRoomTrail');trail.replaceChildren();if(!cityInside)return;const current=document.createElement('span');current.textContent='You are in '+connectionName(connectionKey());trail.append(current);for(const id of (connectionGraph()[connectionKey()]||[]).filter(connectionVisible)){const b=document.createElement('button');b.textContent=connectionName(id);b.dataset.connection=id;b.onclick=()=>connectionGo(id);trail.append(b)}};
const connectionLayoutBefore=cityLayoutPhoto;cityLayoutPhoto=function(){connectionLayoutBefore();connectionLayout()};
const connectionActionsBefore=cityBuildActions;cityBuildActions=function(){connectionActionsBefore();for(const card of $('comfortPlaces').querySelectorAll('.city-action')){const button=card.querySelector('button');if(!button)continue;if(button.dataset.place){const target=button.dataset.place==='owlTreehouse'?'owlPorch':button.dataset.place,path=connections.path(connectionGraph(),connectionKey(),target);if(path.length>1){button.onclick=()=>connectionGo(path[1]);if(path.length>2){button.textContent='Walk via '+connectionName(path[1]);card.querySelector('p').textContent='The entrance to '+connectionName(target)+' is reached through '+connectionName(path[1])+'.';}}}if(button.textContent==='Exit to street'){const back=connectionBack();card.querySelector('h3').textContent='Return the way you came';card.querySelector('p').textContent='The entrance returns to '+connectionName(back)+'.';button.textContent='Return to '+connectionName(back)}}};
const connectionDrawBefore=cityDraw;cityDraw=function(){connectionDrawBefore();if(scene==='home'&&!cityInside)$('hint').textContent='Your cottage door is on the right. The shared lane continues to the left.';else if(cityInside)$('hint').textContent='Connected destinations and their views appear below. Return follows the room’s own entrance.'};comfortDraw=cityDraw;
window.ELDORIA_CONNECTIONS={version:1,get graph(){return connectionGraph()},get location(){return connectionKey()},get routes(){return [...connectionRoutes]},photo:connectionPhoto,go:connectionGo,preview:connectionPreview};cityDraw();
setInterval(()=>{const key=window.ELDORIA_SKY?.phase+':'+atmosphere.conditions(state).weather;if(key===connectionPhotoKey)return;connectionPhotoKey=key;for(const photo of connectionPanel.querySelectorAll('.connection-photo'))connectionPaint(photo,photo.dataset.destination);if($('connectionDoorView'))connectionPaint($('connectionDoorView'),$('connectionDoorView').dataset.destination)},1000);
